<?php require __DIR__.'/_guard.php';if($_SERVER['REQUEST_METHOD']==='POST'){Security::verify();$id=(int)$_POST['id'];$status=$_POST['status'];$allowed=['pending','processing','shipped','delivered','cancelled','returned'];if(in_array($status,$allowed,true)){db()->prepare('UPDATE orders SET order_status=? WHERE id=?')->execute([$status,$id]);audit('order.status','order',$id);}}$orders=db()->query('SELECT id,customer_name,phone,city,grand_total,payment_method,payment_status,order_status,created_at FROM orders ORDER BY id DESC LIMIT 300')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/assets/css/admin.css"></head><body><main class="wide"><a href="/admin/">← Dashboard</a><h1>Orders</h1><table><tr><th>#</th><th>Customer</th><th>City</th><th>Total</th><th>Payment</th><th>Status</th><th>Update</th></tr><?php foreach($orders as $o):?><tr><td><?=$o['id']?></td><td><?=e($o['customer_name'])?><br><?=e($o['phone'])?></td><td><?=e($o['city'])?></td><td><?=money($o['grand_total'])?></td><td><?=e($o['payment_method'])?> / <?=e($o['payment_status'])?></td><td><?=e($o['order_status'])?></td><td><form method="post"><?=Security::field()?><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach(['pending','processing','shipped','delivered','cancelled','returned'] as $st):?><option <?=$st===$o['order_status']?'selected':''?>><?=$st?></option><?php endforeach;?></select><button>Save</button></form></td></tr><?php endforeach;?></table></main></body></html>